CREATE TYPE role AS ENUM ('OWNER','ADMIN','STAFF','CUSTOMER');
CREATE TYPE phone_category AS ENUM ('SMARTPHONE','FEATURE_PHONE');
CREATE TYPE stock_status AS ENUM ('AVAILABLE','RESERVED','SOLD','RETURNED','DEFECTIVE','ARCHIVED');
CREATE TYPE record_status AS ENUM ('ACTIVE','VOIDED','CANCELLED');
CREATE TYPE payment_method AS ENUM ('CASH','CARD','MIXED');
CREATE TABLE users (id bigserial PRIMARY KEY,telegram_id bigint NOT NULL UNIQUE,first_name varchar(120) NOT NULL,last_name varchar(120),username varchar(100),phone varchar(20),role role NOT NULL DEFAULT 'CUSTOMER',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id bigserial PRIMARY KEY,category phone_category NOT NULL,brand varchar(100) NOT NULL DEFAULT '',model varchar(160) NOT NULL,slug varchar(220) NOT NULL UNIQUE,description text,storage varchar(50),ram varchar(50),color varchar(80),condition varchar(50),sale_price bigint NOT NULL,warranty_days integer NOT NULL DEFAULT 0,is_published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_batches (id bigserial PRIMARY KEY,product_id bigint NOT NULL REFERENCES products(id),unit_cost bigint NOT NULL,extra_unit_cost bigint NOT NULL DEFAULT 0,initial_quantity integer NOT NULL,available_quantity integer NOT NULL,defective_quantity integer NOT NULL DEFAULT 0,supplier_name varchar(160),supplier_phone varchar(20),received_by bigint REFERENCES users(id),received_at timestamptz NOT NULL DEFAULT now(),notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT batch_quantities_nonnegative CHECK(initial_quantity>=0 AND available_quantity>=0 AND defective_quantity>=0));
CREATE TABLE inventory_units (id bigserial PRIMARY KEY,product_id bigint NOT NULL REFERENCES products(id),batch_id bigint NOT NULL REFERENCES purchase_batches(id),product_code varchar(40) NOT NULL UNIQUE,imei1 varchar(15) UNIQUE,imei2 varchar(15) UNIQUE,uzimei varchar(60),uzimei_method varchar(120),battery_health varchar(30),face_id varchar(30),true_tone varchar(30),repair text,package_info text,technical_state text,status stock_status NOT NULL DEFAULT 'AVAILABLE',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id bigserial PRIMARY KEY,user_id bigint REFERENCES users(id),name varchar(160) NOT NULL,phone varchar(20) NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sales (id bigserial PRIMARY KEY,number varchar(40) NOT NULL UNIQUE,customer_id bigint REFERENCES customers(id),sold_by bigint NOT NULL REFERENCES users(id),subtotal bigint NOT NULL,paid_amount bigint NOT NULL,debt_amount bigint NOT NULL DEFAULT 0,gross_profit bigint NOT NULL,payment_method payment_method NOT NULL,warranty_days integer NOT NULL DEFAULT 0,status record_status NOT NULL DEFAULT 'ACTIVE',sold_at timestamptz NOT NULL DEFAULT now(),notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sale_items (id bigserial PRIMARY KEY,sale_id bigint NOT NULL REFERENCES sales(id),product_id bigint NOT NULL REFERENCES products(id),inventory_unit_id bigint REFERENCES inventory_units(id),batch_id bigint NOT NULL REFERENCES purchase_batches(id),quantity integer NOT NULL CHECK(quantity>0),unit_sale_price bigint NOT NULL,unit_cost_snapshot bigint NOT NULL,profit_snapshot bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expenses (id bigserial PRIMARY KEY,category varchar(80) NOT NULL,amount bigint NOT NULL,payment_method payment_method NOT NULL,notes text,created_by bigint NOT NULL REFERENCES users(id),expense_date date NOT NULL,status record_status NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_movements (id bigserial PRIMARY KEY,product_id bigint NOT NULL REFERENCES products(id),batch_id bigint REFERENCES purchase_batches(id),type varchar(40) NOT NULL,quantity integer NOT NULL,reference_type varchar(40),reference_id bigint,actor_id bigint REFERENCES users(id),details jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY,actor_id bigint REFERENCES users(id),action varchar(100) NOT NULL,entity_type varchar(60) NOT NULL,entity_id bigint,details jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE telegram_updates (update_id bigint PRIMARY KEY,status varchar(20) NOT NULL DEFAULT 'PROCESSING',processed_at timestamptz,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media (id bigserial PRIMARY KEY,product_id bigint NOT NULL REFERENCES products(id),url text NOT NULL,alt varchar(180) NOT NULL,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_category_idx ON products(category); CREATE INDEX products_published_idx ON products(is_published); CREATE INDEX purchase_batches_product_fifo_idx ON purchase_batches(product_id,received_at); CREATE INDEX inventory_status_idx ON inventory_units(status); CREATE INDEX sales_sold_at_idx ON sales(sold_at,status); CREATE INDEX sale_items_sale_idx ON sale_items(sale_id); CREATE INDEX expenses_date_idx ON expenses(expense_date,status); CREATE INDEX inventory_movements_product_idx ON inventory_movements(product_id,created_at); CREATE INDEX audit_entity_idx ON audit_logs(entity_type,entity_id); CREATE INDEX audit_created_idx ON audit_logs(created_at); CREATE INDEX media_product_idx ON media(product_id,sort_order); CREATE INDEX users_role_idx ON users(role);
